function pauseMenu(){modal(save.lang==='PT'?'Pausa':'Paused',save.lang==='PT'?'Respire. A cidade continua aí.':'Take a breath. The city will be here.',`<div class="missionList"><button class="missionOption" id="resume"><span><b>${save.lang==='PT'?'Continuar':'Resume'}</b><small>${save.lang==='PT'?'Voltar à cidade':'Return to the city'}</small></span><strong>▶</strong></button><button class="missionOption" id="pauseMap"><span><b>${save.lang==='PT'?'Mapa da cidade':'City map'}</b><small>${save.lang==='PT'?'Visualização em tela cheia':'Fullscreen view'}</small></span><strong>⌖</strong></button><button class="missionOption" id="pauseSettings"><span><b>${t('settings')}</b><small>${save.lang==='PT'?'Gráficos, idioma e controles':'Graphics, language and controls'}</small></span><strong>⚙</strong></button><button class="missionOption" id="saveExit"><span><b>${save.lang==='PT'?'Salvar e sair':'Save & exit'}</b><small>${save.lang==='PT'?'Seu progresso fica neste dispositivo':'Your progress stays on this device'}</small></span><strong>↗</strong></button></div>`);$('#resume').onclick=()=>$('#modalRoot').classList.add('hidden');$('#pauseMap').onclick=()=>mapModal();$('#pauseSettings').onclick=()=>settingsModal();$('#saveExit').onclick=()=>{persist();$('#modalRoot').classList.add('hidden');playing=false;$('#game').classList.add('hidden');$('#landing').classList.remove('hidden');toast(t('saved'))}}

/* Motor de cidade — Canvas 2D em projeção aérea original */
function initWorld(){
 canvas=$('#world'); ctx=canvas.getContext('2d',{alpha:false});
 mapCanvas=$('#minimap'); minimapCtx=mapCanvas.getContext('2d');
 resize(); addSeededTraffic(); addPeds();
 window.addEventListener('resize',resize);
 window.addEventListener('keydown',e=>{keys[e.key.toLower=e.key.toLowerCase()]=true;if(e.key==='Escape')pauseMenu();if(e.key.toLowerCase()==='q')switchCharacter();if(e.key.toLowerCase()==='e')interact();if(e.key.toLowerCase()==='f')action()});
 window.addEventListener('keyup',e=>keys[e.key.toLower=e.key.toLowerCase()]=false);
 setupTouch(); requestAnimationFrame(loop);
}
function resize(){
 const q=save.quality==='low'?0.72:(save.quality==='medium'?0.86:1);
 const dpr=Math.min(devicePixelRatio||1,q*(save.quality==='ultra'?1.35:1));
 canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.setTransform(dpr,0,0,dpr,0,0);
 mapCanvas.width=mapCanvas.clientWidth||150;mapCanvas.height=mapCanvas.clientHeight||150;
}
function addSeededTraffic(){
 cars=[];for(let i=0;i<(save.quality==='low'?12:26);i++){cars.push({x:420+(i*173)%2000,y:380+(i*287)%1000,angle:(i%4)*Math.PI/2,ai:i%3===0?'v':'h',color:['#d54b4b','#d8c46c','#3d8294','#d6dde0','#3d4e70'][i%5],speed:25+(i%5)*7})}
 police=[];for(let i=0;i<3;i++)police.push({x:1500+i*180,y:1150-i*90,angle:0});
}
function addPeds(){pedestrians=[];for(let i=0;i<(save.quality==='low'?16:42);i++)pedestrians.push({x:350+(i*241)%1800,y:350+(i*373)%1050,angle:i*.7,speed:7+(i%4),shirt:['#f4ca72','#69aaa1','#d47c70','#dce3d6'][i%4]})}
function startGame(m,n=0){
 mode=m;chapter=n;missionPhase=0;wanted=0;
 const c=chapters[n];position={x:c.from.x,y:c.from.y};vehicle={x:position.x+80,y:position.y,active:false};
 $('#landing').classList.add('hidden');$('#game').classList.remove('hidden');$('#modalRoot').classList.add('hidden');playing=true;
 if(!ctx)initWorld();applyHUD();updateMissionUI();localize();
 if(mode==='story'){dialogue(c.npc,save.lang==='PT'?'Encontre o ponto marcado.':'Reach the marked location.',save.lang==='EN'?'Reach the marked location.':'A cidade mudou desde a última vez.');}
 save.lastMode=m;save.lastChapter=n;persist();
}
function setupTouch(){
 const stick=$('#stick');let active=false,cx=0,cy=0;
 const move=e=>{if(!active)return;const r=stick.getBoundingRect();const t=e.touches?e.touches[0]:e;cx=r.left+r.width/2;cy=r.top+r.height/2;joy.x=Math.max(-1,Math.min(1,(t.clientX-cx)/(r.width*.32)));joy.y=Math.max(-1,Math.min(1,(t.clientY-cy)/(r.height*.32)));stick.style.setProperty('--sx',(joy.x*29)+'px');stick.style.setProperty('--sy',(joy.y*29)+'px')};
 stick.addEventListener('pointerdown',e=>{active=true;stick.setPointerCapture(e.pointerId);move(e)});stick.addEventListener('pointermove',move);const stop=()=>{active=false;joy.x=joy.y=0;stick.style.setProperty('--sx','0px');stick.style.setProperty('--sy','0px')};stick.addEventListener('pointerup',stop);stick.addEventListener('pointercancel',stop);
 $('#runBtn').addEventListener('pointerdown',()=>runHeld=true);$('#runBtn').addEventListener('pointerup',()=>runHeld=false);
 $('#aimBtn').addEventListener('pointerdown',()=>aiming=!aiming);$('#actBtn').onclick=interact;$('#fireBtn').onclick=action;$('#switchBtn').onclick=switchCharacter;$('#mapBtn').onclick=mapModal;$('#mini').onclick=mapModal;
}
function switchCharacter(){character=character?0:1;$('#charName').text=character?'CARLOS • 29':'LUIZA • 24';toast(character?(save.lang==='PT'?'Carlos assumiu o controle':'Carlos has taken control'):(save.lang==='PT'?'Luiza assumiu o controle':'Luiza has taken control'))}
function interact(){
 if(mode==='story'){const c=chapters[chapter];const target=c.to;const d=Math.hypot(position.x-target.x,position.y-target.y);if(d<90)missionComplete();else if(!vehicle.active)dialogue(c.npc,save.lang==='PT'?'Continue até o ponto marcado em verde.':'Keep going toward the green marker.',save.lang==='EN'?'Keep going toward the green marker.':'O sinal da rádio está fraco por aqui.')}
 else{wanted=Math.min(6,wanted+1);updateStars();dialogue('Nina','Tudo bem? Eu vi uma viatura perto da Praia Nova.','Are you okay? I saw a patrol near Praia Nova.')}
}
function action(){if(vehicle.active){vehicle.active=false;toast(save.lang==='PT'?'Você saiu do veículo':'Vehicle exited')}else{const near=distanceTo(vehicle)<75;vehicle.active=near;if(!near)toast(save.lang==='PT'?'Aproxime-se do veículo marcado':'Get closer to the marked vehicle')}}
function distanceTo(o){return Math.hypot(position.x-o.x,position.y-o.y)}
function missionComplete(){
 const c=chapters[chapter];money+=1250;missionPhase=1;save.unlocked=Math.max(save.unlocked||1,Math.min(5,chapter+2));checkpoint={x:c.to.x,y:c.to.y};save.checkpoint=checkpoint;persist();updateMissionUI();dialogue(c.npc,save.lang==='PT'?'Missão concluída. Você deixou uma marca nesta cidade.':'Mission complete. You left a mark on this city.',save.lang==='EN'?'Mission complete. You left a mark on this city.':'Agora a cidade já sabe seu nome.');
 if(chapter===4){toast(save.lang==='PT'?'Costa Viva — final alcançado':'Costa Viva — finale reached');wanted=0}
}
function updateMissionUI(){
 if(mode==='rp'){$('#missionTitle').textContent=save.lang==='PT'?'MODO ROLEPLAY':'ROLEPLAY MODE';$('#objective').textContent=save.lang==='PT'?'Explore Santa Aurora • converse • dirija':'Explore Santa Aurora • talk • drive';return}
 const c=chapters[chapter];$('#missionTitle').textContent=save.lang==='PT'?c.titlePT:c.titleEN;$('#objective').textContent=save.lang==='PT'?c.briefPT:c.briefEN;
}
function mapModal(){
 modal(save.lang==='PT'?'Mapa de Santa Aurora':'Santa Aurora Map',save.lang==='PT'?'Pontos de interesse • objetivo • posição atual':'Points of interest • objective • current position.',`<div class="mapLarge"><canvas id="largeMap"></canvas></div><p class="modalFoot">${save.lang==='PT'?'Use o mapa para orientar suas rotas pela baía.':'Use the map to plan routes around the bay.'}</p>`,'NAVEGAÇÃO');const lc=$('#largeMap');lc.width=lc.clientWidth||780;lc.height=lc.clientHeight||557;drawMap(lc.getContext('2d'),lc.width,lc.height,true)
}
function drawMap(mctx,w,h,large=false){
 mctx.clearRect(0,0,w,h);mctx.fillStyle='#0b3b3c';mctx.fillRect(0,0,w,h);mctx.fillStyle='#1b302a';mctx.beginPath();mctx.moveTo(0,0);mctx.lineTo(w*.22,0);mctx.lineTo(w*.30,h*.28);mctx.lineTo(w*.58,h*.20);mctx.lineTo(w,h*.35);mctx.lineTo(w,h);mctx.lineTo(0,h);mctx.closePath();mctx.fill();
 mctx.strokeStyle='#95a878';mctx.lineWidth=large?7:2;for(let x=20;x<w;x+=w/8){mctx.beginPath();mctx.moveTo(x,0);mctx.bezierCurveTo(x+h*.05,h*.25,x-h*.10,h*.72,x,h);mctx.stroke()}for(let y=15;y<h;y+=h/7){mctx.beginPath();mctx.moveTo(0,y);mctx.bezierCurveTo(w*.25,y+h*.04,w*.75,y-h*.05,w,y);mctx.stroke()}
 const sx=x=>x/city.w*w,sy=y=>y/city.h*h;mctx.fillStyle='#9ec78b';for(const b of [{x:380,y:420,w:220,h:130},{x:800,y:520,w:300,h:180},{x:1250,y:340,w:260,h:150},{x:1700,y:760,w:180,h:240},{x:650,y:1030,w:330,h:160}])mctx.fillRect(sx(b.x),sy(b.y),sx(b.w),sy(b.h));
 if(mode==='story'){const c=chapters[chapter];mctx.fillStyle='#b5ff82';mctx.beginPath();mctx.arc(sx(c.to.x),sy(c.to.y),large?9:4,0,Math.PI*2);mctx.fill()}
 mctx.fillStyle='#fff';mctx.beginPath();mctx.arc(sx(position.x),sy(position.y),large?7:3,0,Math.PI*2);mctx.fill();mctx.fillStyle='#70ddd1';mctx.fillRect(sx(position.x)-2,sy(position.y)-7,4,14);
}
function updateStars(){const filled='★'.repeat(wanted),empty='☆'.repeat(6-wanted);$('#stars').textContent=filled+empty}

function loop(t){
 if(!playing){lastFrame=t;requestAnimationFrame(loop);return}
 delta=Math.min(.035,(t-lastFrame)/1000||.016);lastFrame=t;frame++;worldTime+=delta;update(delta);render(delta);requestAnimationFrame(loop);
}
function update(dt){
 let ix=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+(joy.x||0),iy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+(joy.y||0);
 const len=Math.hypot(ix,iy);if(len>1){ix/=len;iy/=len}const speed=(runHeld||keys.shift?180:110)*(vehicle.active?0:1)*dt;
 if(vehicle.active){vehicle.x=Math.max(40,Math.min(city.w-40,vehicle.x+ix*(speed*1.7)));vehicle.y=Math.max(40,Math.min(city.h-40,vehicle.y+iy*(speed*1.7)));position.x=vehicle.x;position.y=vehicle.y}else{position.x=Math.max(40,Math.min(city.w-40,position.x+ix*speed));position.y=Math.max(40,Math.min(city.h-40,position.y+iy*speed)}
 const targetCameraX=Math.max(0,Math.min(city.w-innerWidth,position.x-innerWidth*.5)),targetCameraY=Math.max(0,Math.min(city.h-innerHeight,position.y-innerHeight*.5));camera.x+=(targetCameraX-camera.x)*.09;camera.y+=(targetCameraY-camera.y)*.09;
 for(const c of cars){if(c.ai==='h'){c.x+=c.speed*dt;if(c.x>2100)c.x=350}else{c.y+=c.speed*dt;if(c.y>1450)c.y=350}}
 for(const p of pedestrians){p.x+=Math.cos(p.angle)*p.speed*dt;p.y+=Math.sin(p.angle)*p.speed*dt;if(p.x<320||p.x>2050||p.y<300||p.y>1450)p.angle+=Math.PI*.7}
 if(wanted>0){wanted=Math.max(0,wanted-dt*.008);updateStars();for(const p of police){const dx=position.x-p.x,dy=position.y-p.y,d=Math.hypot(dx,dy)||1;p.x+=dx/d*(vehicle.active?90:55)*dt;p.y+=dy/d*(vehicle.active?90:55)*dt}}
 const district=position.y<650?'PONTA DO SOL':position.x>1550?'MARÉ CLARA':'CENTRO NOVO';$('#district').textContent=district+' • '+(17+(worldTime/240|0)%5).toString().padStart(2,'0')+':'+(42+(frame%60)|0).toString().padStart(2,'0');
 if(mode==='story'){const c=chapters[chapter],d=Math.hypot(position.x-c.to.x,position.y-c.to.y);if(d<70&&missionPhase===0)missionComplete()}
}
function render(dt){
 const w=innerWidth,h=innerHeight;ctx.clearRect(0,0,w,h);
 const gradient=ctx.createLinearGradient(0,0,0,h);gradient.addColorStop(0,'#76afb0');gradient.addColorStop(.32,'#b5b58f');gradient.addColorStop(.55,'#4d7962');gradient.addColorStop(1,'#102a24');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);
 ctx.save();ctx.translate(-camera.x,-camera.y);
 drawSea();drawWorld();ctx.restore();drawMini();
}
function drawSea(){ctx.fillStyle='#1f7478';ctx.fillRect(-100,-100,city.seaLine+150,city.h+200);ctx.strokeStyle='#77c2bd';ctx.globalAlpha=.5;for(let y=20;y<city.h;y+=38){ctx.beginPath();for(let x=0;x<city.seaLine+100;x+=12){const yy=y+Math.sin(x*.035+worldTime*1.6+y)*3;ctx.lineTo(x,yy)}ctx.stroke()}ctx.globalAlpha=1}
function drawWorld(){
 ctx.fillStyle='#5c7457';ctx.fillRect(city.seaLine,0,city.w-city.seaLine,city.h);ctx.fillStyle='#d7c89c';ctx.fillRect(city.seaLine+10,0,110,city.h);
 ctx.fillStyle='#9d9f81';ctx.fillRect(city.seaLine+145,0,28,city.h);ctx.fillRect(city.seaLine+145,0,city.w-city.seaLine,28);
 for(let x=280;x<city.w;x+=230){for(let y=290;y<city.h;y+=210){ctx.fillStyle='#aeb8a2';ctx.fillRect(x,y,170,135);ctx.fillStyle='#405b50';ctx.fillRect(x+12,y+12,146,111);ctx.fillStyle='#d9b47a';ctx.fillRect(x+22,y+22,126,91);ctx.fillStyle='#596e63';for(let bx=x+34;bx<x+145;bx+=28){for(let by=y+32;by<y+105;by+=24)ctx.fillRect(bx,by,16,12)}}}
 ctx.strokeStyle='#d0bd91';ctx.lineWidth=18;ctx.beginPath();ctx.moveTo(150,650);ctx.lineTo(2100,650);ctx.moveTo(720,300);ctx.lineTo(720,1450);ctx.moveTo(1380,300);ctx.lineTo(1380,1450);ctx.stroke();ctx.strokeStyle='#747b68';ctx.lineWidth=2;ctx.setLineDash([28,22]);ctx.stroke();ctx.setLineDash([]);
 if(save.quality!=='low')drawTrees();drawBuildings();drawRoadObjects();
}
function drawTrees(){for(let i=0;i<70;i++){let x=320+(i*137)%1850,y=320+(i*263)%1140;if(x<city.seaLine+140)continue;ctx.fillStyle='#253e32';ctx.beginPath();ctx.ellipse(x,y,22,12,.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#66865a';ctx.beginPath();ctx.arc(x-5,y-8,12,0,Math.PI*2);ctx.fill()}}
function drawBuildings(){const blocks=[{x:960,y:380,w:260,h:180,c:'#6d7771'},{x:1500,y:440,w:310,h:220,c:'#7f7870'},{x:1050,y:900,w:380,h:170,c:'#8a765f'},{x:470,y:1000,w:250,h:210,c:'#687a72'},{x:1760,y:1040,w:280,h:240,c:'#717568'}];for(const b of blocks){ctx.fillStyle='#263832';ctx.fillRect(b.x+14,b.y+18,b.w,b.h);ctx.fillStyle=b.c;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#d9c68d';for(let x=b.x+20;x<b.x+b.w-20;x+=38)ctx.fillRect(x,b.y+25,18,10)}}
function drawRoadObjects(){
 for(const c of cars){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.angle);ctx.fillStyle='#17201d';ctx.fillRect(-16,-10,32,20);ctx.fillStyle=c.color;ctx.fillRect(-13,-8,26,16);ctx.fillStyle='#b5d4d5';ctx.fillRect(4,-6,8,12);ctx.restore()}
 for(const p of pedestrians){ctx.fillStyle=p.shirt;ctx.beginPath();ctx.arc(p.x,p.y,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#47372c';ctx.beginPath();ctx.arc(p.x,p.y-7,4,0,Math.PI*2);ctx.fill()}
 ctx.fillStyle='#294b78';ctx.beginPath();ctx.arc(vehicle.x,vehicle.y,16,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b4d3d1';ctx.fillRect(vehicle.x-7,vehicle.y-11,14,22);
 const actor=position;ctx.fillStyle=character?'#c6a57d':'#dd9d85';ctx.beginPath();ctx.arc(actor.x,actor.y-8,8,0,Math.PI*2);ctx.fill();ctx.fillStyle=character?'#6b5968':'#5f8f77';ctx.fillRect(actor.x-7,actor.y-2,14,18);
 ctx.fillStyle=aiming?'#ffca78':'#8eff9a';ctx.beginPath();ctx.arc(actor.x,actor.y,2,0,Math.PI*2);ctx.fill();
 if(wanted>0){for(const p of police){ctx.fillStyle='#253c70';ctx.beginPath();ctx.arc(p.x,p.y,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.fillRect(p.x-2,p.y-5,4,10)}}
 if(mode==='story'&&missionPhase===0){const c=chapters[chapter];ctx.fillStyle='#82f07855';ctx.beginPath();ctx.arc(c.to.x,c.to.y,56+Math.sin(worldTime*3)*6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9cff92';ctx.beginPath();ctx.arc(c.to.x,c.to.y,7,0,Math.PI*2);ctx.fill();}
}
function drawMini(){drawMap(minimapCtx,mapCanvas.width,mapCanvas.height,false)}

$('#mapBtn').onclick=mapModal;$('#mini').onclick=mapModal;
initWorld();applyHUD();
</script>
</body>
</html>

